-- F-230 round 6 (batch 2): human Cultist colours -> clean colour + face paint marking.
-- GENERATED by Scripts/Character Skins/markings_regroup.py - do not edit, re-run the script.
-- Idempotent: once per character (zep_f230_markings_round6_done), characters with guid <= 4266 only.
CREATE TABLE IF NOT EXISTS zep_f230_markings_round6_done (guid INT UNSIGNED NOT NULL PRIMARY KEY)
  ENGINE=InnoDB COMMENT='F-230 markings round 6: characters already migrated';
DROP TABLE IF EXISTS zep_tmp_r6_skin, zep_tmp_r6_face, zep_tmp_r6_todo;
CREATE TABLE zep_tmp_r6_skin (race TINYINT UNSIGNED, gender TINYINT UNSIGNED, skin TINYINT UNSIGNED,
  new_skin TINYINT UNSIGNED, face TINYINT UNSIGNED, body TINYINT UNSIGNED, PRIMARY KEY (race, gender, skin));
