CREATE TABLE zep_tmp_r6_face (race TINYINT UNSIGNED, gender TINYINT UNSIGNED, face TINYINT UNSIGNED,
  new_face TINYINT UNSIGNED, mark TINYINT UNSIGNED, PRIMARY KEY (race, gender, face));
CREATE TABLE zep_tmp_r6_todo (guid INT UNSIGNED PRIMARY KEY);
INSERT INTO zep_tmp_r6_todo (guid) SELECT c.guid FROM characters AS c
WHERE c.guid <= 4266 AND c.guid NOT IN (SELECT guid FROM zep_f230_markings_round6_done);
INSERT INTO character_customizations (guid, customization, choice)
SELECT c.guid, 2, s.face FROM characters AS c JOIN zep_tmp_r6_todo AS t ON t.guid = c.guid
JOIN zep_tmp_r6_skin AS s ON s.race = c.race AND s.gender = c.gender AND s.skin = c.skin WHERE s.face <> 0
ON DUPLICATE KEY UPDATE choice = IF(choice = 0, VALUES(choice), choice);
INSERT INTO character_customizations (guid, customization, choice)
SELECT c.guid, 3, s.body FROM characters AS c JOIN zep_tmp_r6_todo AS t ON t.guid = c.guid
JOIN zep_tmp_r6_skin AS s ON s.race = c.race AND s.gender = c.gender AND s.skin = c.skin WHERE s.body <> 0
ON DUPLICATE KEY UPDATE choice = IF(choice = 0, VALUES(choice), choice);
UPDATE characters AS c JOIN zep_tmp_r6_todo AS t ON t.guid = c.guid
JOIN zep_tmp_r6_skin AS s ON s.race = c.race AND s.gender = c.gender AND s.skin = c.skin SET c.skin = s.new_skin;
INSERT INTO character_customizations (guid, customization, choice)
SELECT c.guid, 2, f.mark FROM characters AS c JOIN zep_tmp_r6_todo AS t ON t.guid = c.guid
JOIN zep_tmp_r6_face AS f ON f.race = c.race AND f.gender = c.gender AND f.face = c.face WHERE f.mark <> 0
ON DUPLICATE KEY UPDATE choice = IF(choice = 0, VALUES(choice), choice);
UPDATE characters AS c JOIN zep_tmp_r6_todo AS t ON t.guid = c.guid
JOIN zep_tmp_r6_face AS f ON f.race = c.race AND f.gender = c.gender AND f.face = c.face SET c.face = f.new_face;
INSERT IGNORE INTO zep_f230_markings_round6_done (guid) SELECT guid FROM zep_tmp_r6_todo;
DROP TABLE zep_tmp_r6_skin, zep_tmp_r6_face, zep_tmp_r6_todo;
